          "issues": {
            "type": "array",
            "items": {
              "type": "object",
              "required": [
                "issue_id",
                "category",
                "location",
                "description",
                "evidence",
                "severity",
                "refactoring_action"
              ],
              "additionalProperties": false,
              "properties": {
                "issue_id": {
                  "type": "string"
                },
                "category": {
                  "type": "string",
                  "enum": [
                    "STYLE",
                    "READABILITY",
                    "DESIGN",
                    "MAINTAINABILITY",
                    "STATIC_ERROR",
                    "RUNTIME_ERROR"
                  ]
                },
                "location": {
                  "type": "object",
                  "required": ["start_line", "end_line"],
                  "additionalProperties": false,
                  "properties": {
                    "start_line": {
                      "type": "integer",
                      "minimum": 1
                    },
                    "end_line": {
                      "type": "integer",
                      "minimum": 1
                    }
                  }
                },
                "description": {
                  "type": "string"
                },
                "evidence": {
                  "type": "string"
                },
                "severity": {
                  "type": "string",
                  "enum": ["HIGH", "MEDIUM", "LOW"]
                },
                "refactoring_action": {
                  "type": "string",
                  "description": "High-level refactoring instruction without code"
                }
              }
            }
          }
        }
      }
    },

    "constraints": {
      "type": "object",
      "required": [
        "behavior_preservation",
        "no_new_features"
      ],
      "additionalProperties": false,
      "properties": {
        "behavior_preservation": {
          "type": "boolean",
          "const": true
        },
        "no_new_features": {
          "type": "boolean",
          "const": true
        }
      }
    }
  }
}

