  "/Users/hf/Desktop/refactoring-swarm-template/sandbox/storage.py": "\"\"\"Module for handling student data storage.\"\"\"\nimport json\n\ndef load_students(path):\n    \"\"\"Loads student data from a JSON file at the given path.\n\n    Args:\n        path (str): The file path to load students from.\n\n    Returns:\n        list: A list of student data.\n    \"\"\"\n    with open(path, \"r\", encoding='utf-8') as f:\n        return json.load(f)\n\ndef save_students(path, students):\n    \"\"\"Saves a list of student data to a JSON file at the given path.\n\n    Args:\n        path (str): The file path to save students to.\n        students (list): The list of student data to save.\n    \"\"\"\n    with open(path, \"w\", encoding='utf-8') as f:\n        json.dump(students, f)\n",
  "/Users/hf/Desktop/refactoring-swarm-template/sandbox/student.py": "\"\"\"Module for representing student information and calculating averages.\"\"\"\nclass Student:\n    \"\"\"Represents a student with a name and a list of grades.\"\"\"\n    def __init__(self, name, grades):\n        \"\"\"Initializes a new Student object.\n\n        Args:\n            name (str): The name of the student.\n            grades (list): A list of numerical grades for the student.\n        \"\"\"\n        self.name = name\n        self.grades = list(grades)\n\n    def average(self):\n        \"\"\"Calculates the average grade for the student.\n\n        Returns:\n            float: The average of the student's grades.\n        \"\"\"\n        if not self.grades:\n            return 0.0\n        return sum(self.grades) / len(self.grades)\n\n    def __str__(self):\n        \"\"\"Returns a string representation of the student.\"\"\"\n        return f\"Student(Name: {self.name}, Average: {self.average():.2f})\"\n\n    @classmethod\n    def from_dict(cls, data):\n        \"\"\"\n        Creates a Student object from a dictionary.\n\n        Args:\n            data (dict): A dictionary containing 'name' and 'grades' keys.\n\n        Returns:\n            Student: A new Student object.\n        \"\"\"\n        return cls(data['name'], data['grades'])\n\n    def to_dict(self):\n        \"\"\"\n        Converts the Student object to a dictionary.\n\n        Returns:\n            dict: A dictionary representation of the student.\n        \"\"\"\n        return {'name': self.name, 'grades': self.grades}\n",
  "/Users/hf/Desktop/refactoring-swarm-template/sandbox/main.py": "\"\"\"Main script for managing student data.\"\"\"\nfrom student import Student\nfrom storage import load_students, save_students\n\nDATA_FILE = \"data.json\"\n\ndef _parse_grades_input(grades_str):\n    \"\"\"Parses a comma-separated string of grades into a list of floats.\n\n    Args:\n        grades_str (str): A string containing comma-separated grades.\n\n    Returns:\n        list: A list of float grades.\n    \"\"\"\n    grades = grades_str.split(\",\")\n    return [float(grade.strip()) for grade in grades if grade.strip()]\n\ndef _get_student_input():\n    \"\"\"Gets student name and grades string from user input.\n\n    Returns:\n        tuple: A tuple containing the student's name (str) and grades string (str).\n    \"\"\"\n    name = input(\"Name: \")\n    grades_str = input(\"Grades (comma separated): \")\n    return name, grades_str\n\ndef add_student(students, name, grades):\n    \"\"\"Adds a new student with given name and grades to the student list.\n\n    Args:\n        students (list): The list of student objects to which to add the new student.\n        name (str): The name of the student.\n        grades (list): A list of numerical grades (floats) for the student.\n    \"\"\"\n    student = Student(name, grades)\n    students.append(student)\n\ndef format_student_averages(students):\n    \"\"\"Returns a list of formatted strings showing the name and average grade for each student.\n\n    Args:\n        students (list): The list of student objects to display.\n\n    Returns:\n        list: A list of strings, each representing a student's name and average.\n    \"\"\"\n    results = []\n    for s in students:\n        results.append(f\"{s.name}: {s.average():.2f}\")\n    return results\n\ndef _load_and_initialize_students(data_file):\n    \"\"\"Loads student data from file and initializes Student objects.\"\"\"\n    raw_students_data = load_students(data_file)\n    return [Student.from_dict(d) for d in raw_students_data]\n\ndef _handle_new_student_entry(students):\n    \"\"\"Handles user input for a new student and adds them to the list.\"\"\"\n    name, grades_str = _get_student_input()\n    grades = _parse_grades_input(grades_str)\n    add_student(students, name, grades)\n\ndef _display_all_averages(students):\n    \"\"\"Displays the average grades for all students.\"\"\"\n    averages_to_print = format_student_averages(students)\n    for avg_line in averages_to_print:\n        print(avg_line)\n\ndef _finalize_and_save_students(students, data_file):\n    \"\"\"Converts student objects to dictionaries and saves them to file.\"\"\"\n    saveable_data = [s.to_dict() for s in students]\n    save_students(data_file, saveable_data)\n\ndef run_app():\n    \"\"\"Runs the main application logic for student management.\"\"\"\n    students = _load_and_initialize_students(DATA_FILE)\n    _handle_new_student_entry(students)\n    _display_all_averages(students)\n    _finalize_and_save_students(students, DATA_FILE)\n\nif __name__ == \"__main__\":\n    run_app()\n"
}

