  "/Users/hf/Desktop/refactoring-swarm-template/sandbox/storage.py": "\"\"\"Module for loading and saving student data.\"\"\"\nimport json\n\ndef load_students(path):\n    \"\"\"Loads student data from a JSON file.\"\"\"\n    with open(path, \"r\", encoding=\"utf-8\") as f:\n        return json.load(f)\n\ndef save_students(path, students):\n    \"\"\"Saves student data to a JSON file.\"\"\"\n    with open(path, \"w\", encoding=\"utf-8\") as f:\n        json.dump(students, f)\n",
  "/Users/hf/Desktop/refactoring-swarm-template/sandbox/student.py": "\"\"\"Module for representing and managing student data.\"\"\"\n\nclass Student:\n    \"\"\"Represents a student with a name and a list of grades.\"\"\"\n    def __init__(self, name, grades):\n        self.name = name\n        self.grades = grades\n\n    def average(self):\n        \"\"\"Calculates the average of the student's grades.\n\n        Returns:\n            float: The average grade, or 0 if no grades are available.\n        \"\"\"\n        if not self.grades:\n            return 0\n        return sum(self.grades) / len(self.grades)\n\n    def add_grade(self, grade):\n        \"\"\"Adds a new grade to the student's list of grades.\n\n        Args:\n            grade (float or int): The grade to be added.\n        \"\"\"\n        self.grades.append(grade)\n",
  "/Users/hf/Desktop/refactoring-swarm-template/sandbox/main.py": "\"\"\"Main script to manage student data.\"\"\"\nfrom student import Student\nfrom storage import load_students, save_students\n\nDATA_FILE = \"data.json\"\n\nstudents = load_students(DATA_FILE)\n\ndef add_student():\n    \"\"\"Prompts user for student name and grades, then adds to the student list.\"\"\"\n    name = input(\"Name: \")\n    grades_str = input(\"Grades (comma separated): \")\n    grades = [float(grade.strip()) for grade in grades_str.split(\",\") if grade.strip()]\n    student = Student(name, grades)\n    students.append(student)\n\ndef show_average():\n    \"\"\"Displays the name and average grade for each student.\"\"\"\n    for s in students:\n        print(s.name, s.average())\n\nadd_student()\nshow_average()\nsave_students(DATA_FILE, students)\n",
  "/Users/hf/Desktop/refactoring-swarm-template/sandbox/tests/test_storage.py": "import pytest\nimport os\nimport json\nfrom sandbox.storage import load_students, save_students\nfrom sandbox.student import Student # Needed for the serialization test\n\n@pytest.fixture\ndef temp_json_file(tmp_path):\n    file_path = tmp_path / \"test_data.json\"\n    yield file_path\n    if os.path.exists(file_path):\n        os.remove(file_path)\n\ndef test_load_students_success(temp_json_file):\n    data = [{\"name\": \"Alice\", \"grades\": [90, 85]}, {\"name\": \"Bob\", \"grades\": [70, 75]}]\n    with open(temp_json_file, \"w\", encoding=\"utf-8\") as f:\n        json.dump(data, f)\n    \n    loaded_data = load_students(temp_json_file)\n    assert loaded_data == data\n\ndef test_load_students_file_not_found():\n    with pytest.raises(FileNotFoundError):\n        load_students(\"non_existent_file.json\")\n\ndef test_load_students_empty_file(temp_json_file):\n    # An empty file is not valid JSON and should raise a JSONDecodeError\n    with open(temp_json_file, \"w\", encoding=\"utf-8\") as f:\n        f.write(\"\")\n    with pytest.raises(json.JSONDecodeError):\n        load_students(temp_json_file)\n\ndef test_load_students_invalid_json(temp_json_file):\n    with open(temp_json_file, \"w\", encoding=\"utf-8\") as f:\n        f.write(\"{invalid json]\")\n    with pytest.raises(json.JSONDecodeError):\n        load_students(temp_json_file)\n\ndef test_load_students_non_string_path_type_error():\n    with pytest.raises(TypeError):\n        load_students(123) # Path should be a string\n\ndef test_save_students_success(temp_json_file):\n    data = [{\"name\": \"Alice\", \"grades\": [90, 85]}, {\"name\": \"Bob\", \"grades\": [70, 75]}]\n    save_students(temp_json_file, data)\n    \n    with open(temp_json_file, \"r\", encoding=\"utf-8\") as f:\n        loaded_data = json.load(f)\n    assert loaded_data == data\n\ndef test_save_students_and_load_back(temp_json_file):\n    initial_data = [{\"name\": \"Alice\", \"grades\": [90, 85]}, {\"name\": \"Bob\", \"grades\": [70, 75]}]\n    save_students(temp_json_file, initial_data)\n    loaded_data = load_students(temp_json_file)\n    assert loaded_data == initial_data\n\ndef test_save_students_non_serializable_object_type_error(temp_json_file):\n    # This test directly exposes the bug in main.py where it tries to save\n    # a list of Student objects, which are not JSON serializable by default.\n    student1 = Student(\"Alice\", [90, 85])\n    student2 = Student(\"Bob\", [70, 75])\n    students_list = [student1, student2]\n    \n    with pytest.raises(TypeError) as excinfo:\n        save_students(temp_json_file, students_list)\n    assert \"Object of type Student is not JSON serializable\" in str(excinfo.value)\n\ndef test_save_students_non_string_path_type_error():\n    data = [{\"name\": \"Alice\", \"grades\": [90, 85]}]\n    with pytest.raises(TypeError):\n        save_students(123, data) # Path should be a string\n",
  "/Users/hf/Desktop/refactoring-swarm-template/sandbox/tests/test_main_grade_parsing.py": "import pytest\n\n# Helper function to simulate the grade parsing logic from main.py\ndef parse_grades_from_string(grades_str):\n    # This logic is extracted from main.py's add_student function\n    # grades = [float(grade.strip()) for grade in grades_str.split(\",\") if grade.strip()]\n    if not grades_str.strip():\n        return []\n    return [float(grade.strip()) for grade in grades_str.split(\",\") if grade.strip()]\n\ndef test_parse_grades_from_string_valid_ints():\n    assert parse_grades_from_string(\"90,85,92\") == [90.0, 85.0, 92.0]\n\ndef test_parse_grades_from_string_valid_floats():\n    assert parse_grades_from_string(\"90.5,85.0,92.5\") == [90.5, 85.0, 92.5]\n\ndef test_parse_grades_from_string_mixed_types():\n    assert parse_grades_from_string(\"90,85.0,70\") == [90.0, 85.0, 70.0]\n\ndef test_parse_grades_from_string_empty():\n    assert parse_grades_from_string(\"\") == []\n\ndef test_parse_grades_from_string_only_spaces():\n    assert parse_grades_from_string(\"   \") == []\n\ndef test_parse_grades_from_string_commas_and_spaces():\n    assert parse_grades_from_string(\"  , 90 , , 85.5 , \") == [90.0, 85.5]\n\ndef test_parse_grades_from_string_single_grade():\n    assert parse_grades_from_string(\"100\") == [100.0]\n\ndef test_parse_grades_from_string_non_numeric_chars_value_error():\n    # This tests the technical correctness of input handling - invalid float conversion\n    with pytest.raises(ValueError) as excinfo:\n        parse_grades_from_string(\"90,eighty,70\")\n    assert \"could not convert string to float\" in str(excinfo.value)\n\ndef test_parse_grades_from_string_malformed_float_value_error():\n    # Test a string that float() itself cannot parse\n    with pytest.raises(ValueError) as excinfo:\n        parse_grades_from_string(\"90,85..5,70\")\n    assert \"could not convert string to float\" in str(excinfo.value)\n\ndef test_parse_grades_from_string_valid_float_with_trailing_dot():\n    # Python's float() handles \"85.\" as 85.0, so this should pass.\n    assert parse_grades_from_string(\"90,85.,70\") == [90.0, 85.0, 70.0]\n",
  "/Users/hf/Desktop/refactoring-swarm-template/sandbox/tests/test_student.py": "import pytest\nfrom sandbox.student import Student\n\ndef test_student_init():\n    student = Student(\"Alice\", [90, 85, 92])\n    assert student.name == \"Alice\"\n    assert student.grades == [90, 85, 92]\n\ndef test_student_init_empty_grades():\n    student = Student(\"Bob\", [])\n    assert student.name == \"Bob\"\n    assert student.grades == []\n\ndef test_student_init_grades_not_list_causes_type_error_in_average():\n    # The __init__ method currently allows grades to be any type, but average() expects a list or sequence.\n    # This tests that calling average() with non-list grades raises a TypeError.\n    student = Student(\"Charlie\", \"not_a_list\")\n    assert student.name == \"Charlie\"\n    assert student.grades == \"not_a_list\"\n    with pytest.raises(TypeError):\n        student.average()\n\ndef test_student_average_empty_grades():\n    student = Student(\"Alice\", [])\n    assert student.average() == 0\n\ndef test_student_average_single_grade():\n    student = Student(\"Bob\", [100])\n    assert student.average() == 100.0\n\ndef test_student_average_multiple_grades_int():\n    student = Student(\"Charlie\", [90, 80, 70])\n    assert student.average() == 80.0\n\ndef test_student_average_multiple_grades_float():\n    student = Student(\"David\", [90.5, 85.0, 92.5])\n    assert student.average() == pytest.approx(89.33333333333333, rel=1e-9)\n\ndef test_student_average_grades_with_zero():\n    student = Student(\"Eve\", [100, 0, 50])\n    assert student.average() == 50.0\n\ndef test_student_average_negative_grades():\n    student = Student(\"Frank\", [-10, -20, -30])\n    assert student.average() == -20.0\n\ndef test_student_average_non_numeric_grades_type_error():\n    # Functional error due to type unsafety. `sum` and `len` expect numbers in grades.\n    student = Student(\"Grace\", [90, \"eighty\", 70])\n    with pytest.raises(TypeError):\n        student.average()\n\ndef test_student_add_grade_int():\n    student = Student(\"Heidi\", [80])\n    student.add_grade(90)\n    assert student.grades == [80, 90]\n\ndef test_student_add_grade_float():\n    student = Student(\"Heidi\", [80])\n    student.add_grade(75.5)\n    assert student.grades == [80, 75.5]\n\ndef test_student_add_grade_non_numeric_leads_to_average_type_error():\n    # The current implementation allows adding non-numeric types, which can lead to\n    # runtime errors later (e.g., in average()). This test shows the behavior,\n    # and highlights a potential technical risk.\n    student = Student(\"Ivan\", [70])\n    student.add_grade(\"invalid_grade\")\n    assert student.grades == [70, \"invalid_grade\"]\n    with pytest.raises(TypeError):\n        student.average()\n"
